import { describe, it, before, after } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import { observe, getMetrics, getMetricsSummary } from '../../src/observability/agent-observer.ts';

// observe() persists metrics via appendToLog → isolate to a tmp dir so the tests
// don't pollute the real .pipeline-state/agent-metrics.jsonl.
let tmpDir: string;
before(async () => {
  tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), 'director-test-observer-'));
  process.env.STATE_DIR_OVERRIDE = tmpDir;
});
after(async () => {
  delete process.env.STATE_DIR_OVERRIDE;
  await fs.rm(tmpDir, { recursive: true, force: true });
});

describe('agent-observer', () => {
  it('observe() records a successful execution and returns result + metrics', async () => {
    const baseline = getMetrics().length;
    const { result, metrics } = await observe('test-agent', async () => ({ value: 42 }));
    assert.deepEqual(result, { value: 42 });
    assert.equal(metrics.agentName, 'test-agent');
    assert.equal(metrics.success, true);
    assert.ok(metrics.executionTimeMs >= 0);
    assert.equal(getMetrics().length, baseline + 1);
  });

  it('observe() catches errors without rethrowing and marks success=false', async () => {
    const baseline = getMetrics().length;
    const { result, metrics, error } = await observe('failing-agent', async () => {
      throw new Error('kaboom');
    });
    assert.equal(result, null);
    assert.equal(metrics.success, false);
    assert.equal(metrics.agentName, 'failing-agent');
    assert.equal(getMetrics().length, baseline + 1);
    // Regression: the swallowed error must be surfaced so runPhase can rethrow —
    // without it a thrown phase checkpointed as {status:'complete'} and resume
    // skipped the failed phase forever.
    assert.ok(error instanceof Error);
    assert.equal(error.message, 'kaboom');
  });

  it('observe() treats null result as failure', async () => {
    const { result, metrics, error } = await observe('null-agent', async () => null);
    assert.equal(result, null);
    assert.equal(metrics.success, false);
    // A null return is a soft failure, not a throw — no error is surfaced, so
    // runPhase still checkpoints it (phases may legitimately return nothing).
    assert.equal(error, undefined);
  });

  // Regression: the old `result !== null` flagged an `undefined` return as a
  // success (undefined !== null === true).
  it('observe() treats undefined result as failure', async () => {
    const { metrics } = await observe('undef-agent', async () => undefined);
    assert.equal(metrics.success, false);
  });

  it('observe() treats a returned object as success', async () => {
    const { metrics } = await observe('obj-agent', async () => ({ score: 7 }));
    assert.equal(metrics.success, true);
  });

  // Regression: tokensUsed was a TS-only cast — a string '300' was stored as a
  // string at runtime, breaking downstream cost math. It must be coerced.
  it('observe() coerces a string tokensUsed to a number', async () => {
    const { metrics } = await observe('tok-string', async () => ({ tokensUsed: '300' }));
    assert.equal(metrics.tokensUsed, 300);
    assert.equal(typeof metrics.tokensUsed, 'number');
  });

  it('observe() defaults a missing/garbage tokensUsed to 0', async () => {
    const a = await observe('tok-missing', async () => ({ ok: true }));
    assert.equal(a.metrics.tokensUsed, 0);
    const b = await observe('tok-garbage', async () => ({ tokensUsed: 'lots' }));
    assert.equal(b.metrics.tokensUsed, 0);
  });

  it('getMetricsSummary aggregates counts correctly', async () => {
    await observe('summary-agent', async () => ({ ok: true }));
    const summary = getMetricsSummary();
    assert.ok(summary.total >= 1);
    assert.ok(summary.succeeded >= 1);
    assert.equal(typeof summary.failed, 'number');
    assert.equal(typeof summary.totalCost, 'number');
    assert.equal(typeof summary.totalTimeMs, 'number');
  });

  it('getMetrics returns a copy, not the live buffer', async () => {
    const a = getMetrics();
    const b = getMetrics();
    assert.notEqual(a, b, 'should return defensive copy');
    assert.deepEqual(a, b, 'contents should be equal');
  });
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { pickTargetDims } from '../../src/agents/comparator-media.ts';
import { buildComparisonPrompt } from '../../src/agents/video-comparator.ts';

test('pickTargetDims', async (t) => {
  await t.test('matched pairs need no normalization', () => {
    assert.equal(pickTargetDims({ width: 1920, height: 1080 }, { width: 1920, height: 1080 }), null);
  });
  await t.test('the live case: 1080p draft vs 720p baseline → downscale to 720p', () => {
    assert.deepEqual(
      pickTargetDims({ width: 1280, height: 720 }, { width: 1920, height: 1080 }),
      { width: 1280, height: 720 },
    );
    assert.deepEqual(
      pickTargetDims({ width: 1920, height: 1080 }, { width: 1280, height: 720 }),
      { width: 1280, height: 720 },
    );
  });
  await t.test('equal height falls back to smaller width', () => {
    assert.deepEqual(
      pickTargetDims({ width: 1920, height: 1080 }, { width: 1440, height: 1080 }),
      { width: 1440, height: 1080 },
    );
  });
});

test('buildComparisonPrompt', async (t) => {
  await t.test('carries the product-fidelity dimensions as critical', () => {
    const p = buildComparisonPrompt();
    assert.match(p, /product_identity \(CRITICAL\)/);
    assert.match(p, /brand_assets \(CRITICAL\)/);
    assert.match(p, /caps that video's overall score/);
  });
  await t.test('declares resolution a non-signal (inputs are normalized)', () => {
    const p = buildComparisonPrompt();
    assert.match(p, /normalized to the same resolution/);
    assert.match(p, /NOT quality signals/);
  });
  await t.test('embeds the product context only when provided', () => {
    assert.match(buildComparisonPrompt('Aether is a titanium smart ring.'), /titanium smart ring/);
    assert.doesNotMatch(buildComparisonPrompt(), /---/);
  });
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { buildFidelityPrompt, buildStoryboardContext, fidelityPassed } from '../../src/agents/fidelity-gate.ts';
import type { ShotPlan } from '../../src/schemas/shot-plan.ts';
import { FidelityReportSchema, type FidelityReport } from '../../src/schemas/fidelity.ts';
import { frameDiffScore } from '../../src/rendering/tail-check.ts';

const dim = (score: number) => ({ score, notes: 'n' });
const report = (over: Partial<FidelityReport> = {}): FidelityReport => ({
  product_identity: dim(5), brand_assets: dim(5), cta_ending: dim(5),
  motion_artifacts: dim(4), script_alignment: dim(4),
  passed: true, failures: [], ...over,
});

test('buildFidelityPrompt', async (t) => {
  await t.test('carries the three CRITICAL dimensions and the resolution guard', () => {
    const p = buildFidelityPrompt();
    assert.match(p, /product_identity \(CRITICAL\)/);
    assert.match(p, /brand_assets \(CRITICAL\)/);
    assert.match(p, /cta_ending \(CRITICAL\)/);
    assert.match(p, /Resolution.*NOT quality signals/s);
  });
  await t.test('embeds the product/script context when given', () => {
    assert.match(buildFidelityPrompt('titanium smart ring'), /titanium smart ring/);
    assert.doesNotMatch(buildFidelityPrompt(), /---/);
  });
});

test('fidelityPassed — judge half: identity + brand only', async (t) => {
  await t.test('passes when identity and brand clear the threshold', () => {
    assert.equal(fidelityPassed(report()), true);
  });
  await t.test('identity or brand below threshold fails', () => {
    // The owner's exact case: a flattering judge while identity failed.
    assert.equal(fidelityPassed(report({ product_identity: dim(2) })), false);
    assert.equal(fidelityPassed(report({ brand_assets: dim(1) })), false);
  });
  await t.test('cta and the judge boolean are excluded — the deterministic tail check owns the ending', () => {
    // Calibration: the judge mis-read the final seconds even with the exact
    // last frame attached; its cta score and passed flag must not block here.
    assert.equal(fidelityPassed(report({ cta_ending: dim(1), passed: false })), true);
  });
  await t.test('non-critical dimensions never block', () => {
    assert.equal(fidelityPassed(report({ motion_artifacts: dim(1) })), true);
  });
});

test('FidelityReportSchema rejects malformed payloads', () => {
  assert.throws(() => FidelityReportSchema.parse({ passed: true }));
  assert.ok(FidelityReportSchema.parse(report()));
});

test('frameDiffScore', async (t) => {
  await t.test('identical frames score 0', () => {
    const a = Buffer.alloc(4096, 128);
    assert.equal(frameDiffScore(a, Buffer.from(a)), 0);
  });
  await t.test('opposite frames score 1', () => {
    assert.equal(frameDiffScore(Buffer.alloc(64, 0), Buffer.alloc(64, 255)), 1);
  });
  await t.test('throws on mismatched or empty buffers instead of a silent pass', () => {
    assert.throws(() => frameDiffScore(Buffer.alloc(4), Buffer.alloc(8)), /equal-length/);
    assert.throws(() => frameDiffScore(Buffer.alloc(0), Buffer.alloc(0)), /equal-length/);
  });
});

const VILLAIN_PLAN: ShotPlan = {
  product_bible: 'A sleek titanium smart ring with no screen.',
  hero_prompt: 'Beauty shot of the titanium ring.',
  tone: 'calm',
  color_palette: 'muted slate',
  shots: [
    { scene_id: 'shot_00_problem', beat: 'Notification overload', shows_product: false,
      prompt: 'Extreme close-up on a generic smartwatch aggressively flashing notifications', camera: 'push-in' },
    { scene_id: 'shot_01_relief', beat: 'Enter the ring', shows_product: true,
      prompt: 'The ring sliding gracefully onto a finger', camera: 'macro' },
  ],
};

test('buildStoryboardContext — designed contrast is stated, not excused', async (t) => {
  const ctx = buildStoryboardContext(VILLAIN_PLAN);

  await t.test('labels every shot with its intent, in order', () => {
    assert.match(ctx, /0\. \[CONTRAST — deliberately NOT the product\] Extreme close-up on a generic smartwatch/);
    assert.match(ctx, /1\. \[PRODUCT\] The ring sliding gracefully/);
  });

  await t.test('tells the judge contrast shots are intent — and product shots still bind', () => {
    assert.match(ctx, /NOT a product-identity or script failure/);
    assert.match(ctx, /\[PRODUCT\] shot showing a different object is still a failure/);
  });

  await t.test('long prompts are truncated so the storyboard cannot flood the judge prompt', () => {
    const long: ShotPlan = { ...VILLAIN_PLAN, shots: [{ ...VILLAIN_PLAN.shots[0], prompt: 'x'.repeat(600) }] };
    const line = buildStoryboardContext(long).split('\n')[1];
    assert.ok(line.length < 230, `storyboard line too long: ${line.length}`);
  });
});

test('buildFidelityPrompt embeds the storyboard section only when given', async (t) => {
  await t.test('storyboard present', () => {
    const p = buildFidelityPrompt('a ring', buildStoryboardContext(VILLAIN_PLAN));
    assert.match(p, /Storyboard \(the art director's plan/);
    assert.match(p, /\[CONTRAST — deliberately NOT the product\]/);
  });
  await t.test('no storyboard, no section', () => {
    assert.doesNotMatch(buildFidelityPrompt('a ring'), /Storyboard/);
  });
});

/**
 * ObservabilityAgent — monitors agent execution, logs metrics.
 * Wraps any agent function to capture timing, tokens, cost, and success.
 */
import type { AgentMetrics } from '../types/index.ts';
import { appendToLog } from '../pipeline/state.ts';

const metricsBuffer: AgentMetrics[] = [];

/**
 * Wrap an agent function with observability tracking.
 *
 * Never rethrows — metrics must persist even for a failed call — but a thrown
 * error is surfaced on the `error` field so callers with a failure contract
 * (runPhase's checkpoint) can rethrow it. `result ?? fallback` alone cannot
 * distinguish "threw" from "legitimately returned undefined", which is how a
 * failed b-roll phase got checkpointed as complete and resume skipped it.
 */
export function observe<T>(
  agentName: string,
  fn: () => Promise<T>,
): Promise<{ result: T | null; metrics: AgentMetrics; error?: unknown }> {
  return observeAgent(agentName, fn);
}

async function observeAgent<T>(
  agentName: string,
  fn: () => Promise<T>,
): Promise<{ result: T | null; metrics: AgentMetrics; error?: unknown }> {
  const start = Date.now();
  const retries = 0;
  let threw = false;
  let caught: unknown;
  let result: T | null = null;

  try {
    result = await fn();
  } catch (err) {
    threw = true;
    caught = err;
    console.error(`[Observer] ${agentName} threw: ${err instanceof Error ? err.message : String(err)}`);
  }

  // Success = completed without throwing AND returned a defined, non-null value.
  // `result != null` catches both null and undefined (the old `!== null` marked
  // an `undefined` return as a success).
  const success = !threw && result != null;
  const executionTimeMs = Date.now() - start;

  // tokensUsed is cast from an unknown result shape — coerce at runtime so a
  // string like '300' becomes the number 300 rather than violating the declared
  // `number` type (a TS-only cast left it as a string, breaking downstream math).
  const tokensNum = Number((result as Record<string, unknown> | null)?.tokensUsed);

  const metrics: AgentMetrics = {
    agentName,
    executionTimeMs,
    tokensUsed: Number.isFinite(tokensNum) ? tokensNum : 0,
    costEstimate: estimateCost(executionTimeMs),
    success,
    retries,
    timestamp: new Date().toISOString(),
  };

  metricsBuffer.push(metrics);

  // Persist to log
  await appendToLog('agent-metrics.jsonl', metrics as unknown as Record<string, unknown>);

  const status = success ? 'OK' : 'FAIL';
  console.log(
    `[Observer] ${agentName}: ${status} (${(executionTimeMs / 1000).toFixed(1)}s, ~$${metrics.costEstimate.toFixed(4)})`,
  );

  return threw ? { result, metrics, error: caught } : { result, metrics };
}

/**
 * Get all collected metrics for this session.
 */
export function getMetrics(): AgentMetrics[] {
  return [...metricsBuffer];
}

/**
 * Get summary of all agent executions.
 */
export function getMetricsSummary(): {
  total: number;
  succeeded: number;
  failed: number;
  totalTimeMs: number;
  totalCost: number;
} {
  const succeeded = metricsBuffer.filter((m) => m.success).length;
  return {
    total: metricsBuffer.length,
    succeeded,
    failed: metricsBuffer.length - succeeded,
    totalTimeMs: metricsBuffer.reduce((sum, m) => sum + m.executionTimeMs, 0),
    totalCost: metricsBuffer.reduce((sum, m) => sum + m.costEstimate, 0),
  };
}

function estimateCost(executionTimeMs: number): number {
  // Rough estimate: ~$0.001 per second of Gemini API usage
  return (executionTimeMs / 1000) * 0.001;
}

/**
 * EvaluationAgent — scores agent group quality.
 * Groups agents by domain, evaluates each group's collective output quality.
 */
import type { AgentMetrics, PolicyViolation, GroupEvaluation } from '../types/index.ts';
import { getMetrics } from './agent-observer.ts';
import { enforcePolicy } from '../policies/policy-enforcer.ts';
import { AGENT_EXECUTION_POLICY } from '../policies/policy-creator.ts';

export type { GroupEvaluation } from '../types/index.ts';

const AGENT_GROUPS: Record<string, string[]> = {
  scoring: ['VideoScorer', 'ScriptScorer', 'SceneAnalyzer'],
  creative: ['CreativeDirector', 'AcousticAnalyzer'],
  comparison: ['VideoComparator'],
  pipeline: ['runner'],
};

/**
 * Evaluate all agent groups.
 */
export function evaluateAllGroups(): GroupEvaluation[] {
  const metrics = getMetrics();
  return Object.entries(AGENT_GROUPS).map(([group, agentNames]) =>
    evaluateGroup(group, agentNames, metrics),
  );
}

function evaluateGroup(
  group: string,
  agentNames: string[],
  allMetrics: AgentMetrics[],
): GroupEvaluation {
  const groupMetrics = allMetrics.filter((m) =>
    agentNames.some((name) => m.agentName.includes(name)),
  );

  if (groupMetrics.length === 0) {
    return {
      group,
      agents: agentNames,
      avgExecutionMs: 0,
      successRate: 1.0,
      totalCost: 0,
      policyViolations: [],
      grade: 'A',
    };
  }

  const avgExecutionMs =
    groupMetrics.reduce((sum, m) => sum + m.executionTimeMs, 0) / groupMetrics.length;
  const successRate =
    groupMetrics.filter((m) => m.success).length / groupMetrics.length;
  const totalCost = groupMetrics.reduce((sum, m) => sum + m.costEstimate, 0);

  // Check each agent's metrics against execution policy
  const violations = groupMetrics.flatMap((m) =>
    enforcePolicy(AGENT_EXECUTION_POLICY, m as unknown as Record<string, unknown>),
  );

  const grade = calculateGrade(successRate, violations.length, avgExecutionMs);

  return { group, agents: agentNames, avgExecutionMs, successRate, totalCost, policyViolations: violations, grade };
}

function calculateGrade(
  successRate: number,
  violationCount: number,
  avgMs: number,
): 'A' | 'B' | 'C' | 'D' | 'F' {
  if (successRate === 1.0 && violationCount === 0 && avgMs < 60000) return 'A';
  if (successRate >= 0.9 && violationCount <= 1) return 'B';
  if (successRate >= 0.7 && violationCount <= 3) return 'C';
  if (successRate >= 0.5) return 'D';
  return 'F';
}

/**
 * Print evaluation report.
 */
export function printEvaluationReport(evaluations: GroupEvaluation[]): void {
  console.log(`\n${'='.repeat(50)}`);
  console.log(`  AGENT GROUP EVALUATIONS`);
  console.log(`${'='.repeat(50)}`);
  for (const e of evaluations) {
    console.log(
      `  [${e.grade}] ${e.group}: ${(e.successRate * 100).toFixed(0)}% success, ` +
      `${(e.avgExecutionMs / 1000).toFixed(1)}s avg, $${e.totalCost.toFixed(4)}, ` +
      `${e.policyViolations.length} violations`,
    );
  }
  console.log(`${'='.repeat(50)}\n`);
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { composeCreativeInput } from '../../src/agents/creative-director.ts';

test('composeCreativeInput', async (t) => {
  await t.test('includes the project title and full script', () => {
    const out = composeCreativeInput('Tara: launch', 'Meet Tara.');
    assert.ok(out.includes('Project: Tara: launch'));
    assert.ok(out.includes('SCRIPT:\nMeet Tara.'));
