    const out = composeCreativeInput('T', 'script');
    assert.ok(out.includes('creative director'));
  });
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { pacedVideoCall, isRateLimitError, resetVideoPacing, RATE_LIMIT_BACKOFF_MS } from '../../src/generators/pacing.ts';

function makeClock() {
  let t = 100_000;
  const sleeps: number[] = [];
  return {
    now: () => t,
    sleep: (ms: number) => {
      sleeps.push(ms);
      t += ms;
      return Promise.resolve();
    },
    advance: (ms: number) => { t += ms; },
    sleeps,
  };
}

test('isRateLimitError', () => {
  assert.equal(isRateLimitError(new Error('Replicate rate limit exceeded. Back off and retry.')), true);
  assert.equal(isRateLimitError(new Error('Request was throttled.')), true);
  assert.equal(isRateLimitError(new Error('predictions submit failed: 429 — {"detail":"..."}')), true);
  assert.equal(isRateLimitError(new Error('Replicate predictions submit failed: 404')), false);
  assert.equal(isRateLimitError(new Error('no video buffer returned')), false);
});

test('pacedVideoCall', async (t) => {
  await t.test('interval 0: no sleeps, single attempt', async () => {
    resetVideoPacing();
    const clock = makeClock();
    const out = await pacedVideoCall(async () => 'ok', { intervalMs: 0, retryDelaysMs: RATE_LIMIT_BACKOFF_MS, ...clock });
    assert.equal(out, 'ok');
    assert.deepEqual(clock.sleeps, []);
  });

  await t.test('second submit inside the interval waits out the remainder', async () => {
    resetVideoPacing();
    const clock = makeClock();
    const opts = { intervalMs: 12_000, retryDelaysMs: RATE_LIMIT_BACKOFF_MS, ...clock };
    await pacedVideoCall(async () => 1, opts);
    clock.advance(3_000);
    await pacedVideoCall(async () => 2, opts);
    assert.deepEqual(clock.sleeps, [9_000]);
  });

  await t.test('rate-limit errors retry through the backoff schedule, then succeed', async () => {
    resetVideoPacing();
    const clock = makeClock();
    let calls = 0;
    const out = await pacedVideoCall(
      async () => {
        calls++;
        if (calls < 3) throw new Error('Replicate rate limit exceeded. Back off and retry.');
        return 'clip';
      },
      { intervalMs: 0, retryDelaysMs: [15_000, 35_000], ...clock },
    );
    assert.equal(out, 'clip');
    assert.equal(calls, 3);
    assert.deepEqual(clock.sleeps, [15_000, 35_000]);
  });

  await t.test('non-rate-limit errors propagate immediately, no retry', async () => {
    resetVideoPacing();
    const clock = makeClock();
    let calls = 0;
    await assert.rejects(
      pacedVideoCall(
        async () => { calls++; throw new Error('Replicate predictions submit failed: 404'); },
        { intervalMs: 0, retryDelaysMs: [15_000], ...clock },
      ),
      /404/,
    );
    assert.equal(calls, 1);
    assert.deepEqual(clock.sleeps, []);
  });

  await t.test('exhausted backoff schedule rethrows the rate-limit error', async () => {
    resetVideoPacing();
    const clock = makeClock();
    let calls = 0;
    await assert.rejects(
      pacedVideoCall(
        async () => { calls++; throw new Error('Request was throttled.'); },
        { intervalMs: 0, retryDelaysMs: [10, 20], ...clock },
      ),
      /throttled/,
    );
    assert.equal(calls, 3);
  });
});

import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import {
  enforcePolicy,
  enforceAllPolicies,
  passesAllPolicies,
} from '../../src/policies/policy-enforcer.ts';
import type { Policy } from '../../src/types/index.ts';

const minPolicy: Policy = {
  name: 'min-score',
  description: 'Score must be at least 9.0',
  severity: 'error',
  rules: [{ field: 'score', condition: 'min', value: 9.0, message: 'score too low' }],
};

const maxPolicy: Policy = {
  name: 'max-duration',
  description: 'Duration must not exceed 180s',
  severity: 'warning',
  rules: [{ field: 'duration', condition: 'max', value: 180, message: 'too long' }],
};

const containsPolicy: Policy = {
  name: 'required-word',
  description: 'Title must contain "demo"',
  severity: 'warning',
  rules: [{ field: 'title', condition: 'contains', value: 'demo', message: 'missing demo' }],
};

const regexPolicy: Policy = {
  name: 'version-format',
  description: 'version must match vX.Y.Z',
  severity: 'error',
  rules: [{ field: 'version', condition: 'regex', value: '^v\\d+\\.\\d+\\.\\d+$', message: 'bad version' }],
};

const equalsPolicy: Policy = {
  name: 'status-ok',
  description: 'status must equal ok',
  severity: 'info',
  rules: [{ field: 'status', condition: 'equals', value: 'ok', message: 'not ok' }],
};

describe('enforcePolicy', () => {
  it('passes when min rule is satisfied', () => {
    assert.deepEqual(enforcePolicy(minPolicy, { score: 9.5 }), []);
  });

  it('violates when min rule is not satisfied', () => {
    const v = enforcePolicy(minPolicy, { score: 8.5 });
    assert.equal(v.length, 1);
    assert.equal(v[0].actual, 8.5);
    assert.equal(v[0].expected, 9.0);
    assert.equal(v[0].severity, 'error');
  });

  it('passes when max rule is satisfied', () => {
    assert.deepEqual(enforcePolicy(maxPolicy, { duration: 120 }), []);
  });

  it('violates when max is exceeded', () => {
    assert.equal(enforcePolicy(maxPolicy, { duration: 200 }).length, 1);
  });

  it('treats max on arrays as length check', () => {
    const policy: Policy = {
      name: 'max-items',
      description: 'items array must have at most 3 items',
      severity: 'warning',
      rules: [{ field: 'items', condition: 'max', value: 3, message: 'too many items' }],
    };
    assert.equal(enforcePolicy(policy, { items: [1, 2] }).length, 0);
    assert.equal(enforcePolicy(policy, { items: [1, 2, 3, 4] }).length, 1);
  });

  it('violates when contains rule not met', () => {
    assert.equal(enforcePolicy(containsPolicy, { title: 'product launch' }).length, 1);
    assert.equal(enforcePolicy(containsPolicy, { title: 'demo video' }).length, 0);
  });

  it('violates when regex does not match', () => {
    assert.equal(enforcePolicy(regexPolicy, { version: '1.0' }).length, 1);
    assert.equal(enforcePolicy(regexPolicy, { version: 'v1.0.0' }).length, 0);
  });

  it('violates when equals rule not met', () => {
    assert.equal(enforcePolicy(equalsPolicy, { status: 'error' }).length, 1);
    assert.equal(enforcePolicy(equalsPolicy, { status: 'ok' }).length, 0);
  });

  it('handles nested field paths via dot notation', () => {
    const policy: Policy = {
      name: 'nested',
      description: 'metrics.score must be at least 8',
      severity: 'error',
      rules: [{ field: 'metrics.score', condition: 'min', value: 8, message: 'nested low' }],
    };
    assert.equal(enforcePolicy(policy, { metrics: { score: 9 } }).length, 0);
    assert.equal(enforcePolicy(policy, { metrics: { score: 5 } }).length, 1);
  });

  it('treats missing nested fields as undefined (no violation from min/max)', () => {
    assert.deepEqual(enforcePolicy(minPolicy, {}), []);
  });

  // Regression: NaN is `typeof 'number'` but every comparison with it is false,
  // so the old `actual < value` silently satisfied a min bound. A corrupt score
  // (e.g. from a failed parseInt) must be reported, not pass the gate.
  it('reports a NaN field as a min violation', () => {
    assert.equal(enforcePolicy(minPolicy, { score: NaN }).length, 1);
  });

  it('reports a NaN field as a max violation', () => {
    assert.equal(enforcePolicy(maxPolicy, { duration: NaN }).length, 1);
  });

  it('still passes a valid number at the exact min/max bound', () => {
    assert.deepEqual(enforcePolicy(minPolicy, { score: 9.0 }), []);
    assert.deepEqual(enforcePolicy(maxPolicy, { duration: 180 }), []);
  });
});

describe('enforceAllPolicies', () => {
  it('aggregates violations across policies', () => {
    const violations = enforceAllPolicies(
      [minPolicy, maxPolicy],
      { score: 5, duration: 500 },
    );
    assert.equal(violations.length, 2);
  });
});

describe('passesAllPolicies', () => {
  it('passes when only non-error violations exist', () => {
    const result = passesAllPolicies([maxPolicy], { duration: 200 });
    assert.equal(result.passed, true);
    assert.equal(result.violations.length, 1);
  });

  it('fails when any error-severity violation exists', () => {
    const result = passesAllPolicies([minPolicy, maxPolicy], { score: 5, duration: 200 });
    assert.equal(result.passed, false);
    assert.equal(result.violations.length, 2);
  });

  it('passes when all rules satisfied', () => {
    const result = passesAllPolicies([minPolicy, maxPolicy], { score: 10, duration: 120 });
    assert.equal(result.passed, true);
    assert.equal(result.violations.length, 0);
  });
});

import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { exponentialBackoff, sleep, isQuotaError } from '../../src/utils/rate-limit.ts';

describe('isQuotaError', () => {
  it('matches genuine quota / rate-limit markers', () => {
    for (const m of ['HTTP 429', 'RESOURCE_EXHAUSTED', 'quota exceeded', 'Rate limit reached', 'rate_limit', 'rate-limit', 'Too Many Requests']) {
      assert.equal(isQuotaError(m), true, `should match: ${m}`);
    }
  });

  // Regression: the old bare includes('rate') fired on these, wrongly applying
  // exponential backoff to non-quota errors.
  it('does NOT match innocent messages that merely contain "rate"', () => {
    for (const m of ['failed to iterate results', 'moderate rate of failures', 'exchange rate unavailable', 'could not generate image']) {
      assert.equal(isQuotaError(m), false, `should not match: ${m}`);
    }
  });
});

describe('exponentialBackoff', () => {
  it('returns success on first attempt when fn succeeds', async () => {
    const result = await exponentialBackoff(async () => 'ok', 3, 1);
    assert.equal(result.success, true);
    if (result.success) assert.equal(result.value, 'ok');
  });

  it('retries then succeeds', async () => {
    let attempts = 0;
    const result = await exponentialBackoff(
      async () => {
        attempts++;
        if (attempts < 3) throw new Error('transient');
        return 'finally';
      },
      5,
      1,
    );
    assert.equal(result.success, true);
    assert.equal(attempts, 3);
    if (result.success) assert.equal(result.value, 'finally');
  });

  it('returns failure after exhausting retries', async () => {
    const result = await exponentialBackoff(
      async () => {
        throw new Error('permanent failure');
      },
      2,
      1,
    );
    assert.equal(result.success, false);
    if (!result.success) assert.match(result.error, /permanent failure/);
  });

  it('never throws — always returns discriminated union', async () => {
    const result = await exponentialBackoff(
      async () => {
        throw new Error('boom');
      },
      1,
      1,
    );
    assert.equal(result.success, false);
  });

  it('handles non-Error throws', async () => {
    const result = await exponentialBackoff(
      async () => {
        throw 'string rejection';
      },
      1,
      1,
    );
    assert.equal(result.success, false);
    if (!result.success) assert.match(result.error, /string rejection/);
  });
});

describe('sleep', () => {
  it('resolves after at least the specified delay', async () => {
    const start = Date.now();
    await sleep(50);
    const elapsed = Date.now() - start;
    assert.ok(elapsed >= 45, `expected >= 45ms, got ${elapsed}ms`);
  });
});

name: PR Quality Score Gate

# Runs the Director script scorer on PRs and posts the score as a comment.
# Activation: add repo secret GOOGLE_APPLICATION_CREDENTIALS_JSON (a Vertex
# service-account key JSON); optional GOOGLE_CLOUD_PROJECT, VERTEX_LOCATION,
# and PR_SCORE_THRESHOLD (default 7.0). Without the credentials secret the job
# self-skips with a notice (never blocks a PR), so it's safe to keep enabled.

on:
  pull_request:
    branches: [release, main]
    types: [opened, synchronize, reopened, ready_for_review]

permissions:
  contents: read
  pull-requests: write

# Don't pile up score runs on rapid pushes — keep only the latest per PR.
concurrency:
  group: score-pr-${{ github.event.pull_request.number }}
  cancel-in-progress: true

jobs:
  score:
    if: github.event.pull_request.draft == false
    runs-on: ubuntu-latest
    timeout-minutes: 20

    steps:
      - uses: actions/checkout@v7

      - name: Setup Node
        uses: actions/setup-node@v7
        with:
          node-version: '22'
          cache: npm

      - name: Install
        run: npm ci

      - name: Auth Google Cloud
        env:
          GOOGLE_CREDS_JSON: ${{ secrets.GOOGLE_APPLICATION_CREDENTIALS_JSON }}
          GCP_PROJECT: ${{ secrets.GOOGLE_CLOUD_PROJECT }}
          VERTEX_LOC: ${{ secrets.VERTEX_LOCATION }}
        run: |
          if [ -z "$GOOGLE_CREDS_JSON" ]; then
            echo "::notice::Vertex credentials not configured — score gate will skip."
            exit 0
          fi
          echo "$GOOGLE_CREDS_JSON" > /tmp/sa.json
          echo "GOOGLE_APPLICATION_CREDENTIALS=/tmp/sa.json" >> "$GITHUB_ENV"
          echo "GOOGLE_CLOUD_PROJECT=$GCP_PROJECT" >> "$GITHUB_ENV"
          echo "VERTEX_PROJECT=$GCP_PROJECT" >> "$GITHUB_ENV"
          echo "VERTEX_LOCATION=${VERTEX_LOC:-us-central1}" >> "$GITHUB_ENV"
          echo "MODEL=gemini-2.5-flash" >> "$GITHUB_ENV"

      - name: Score test fixture script via Vertex
        if: ${{ env.GOOGLE_APPLICATION_CREDENTIALS != '' }}
        env:
          AGENT_PROVIDER: vertex
          PRODUCT_NAME: Tara
          PRODUCT_DESCRIPTION: an AI coding agent that lives in Slack
          PR_SCORE_THRESHOLD: ${{ secrets.PR_SCORE_THRESHOLD || '7.0' }}
        run: |
          node --import tsx -e "
            import 'dotenv/config';
            import fs from 'fs/promises';
            import { NeuroLink } from '@juspay/neurolink';
            import { runScriptScorerAgent } from './src/agents/script-scorer.ts';
            const nl = new NeuroLink();
            const text = await fs.readFile('tests/fixtures/script.md', 'utf-8');
            const r = await runScriptScorerAgent(nl, text);
            await fs.writeFile('output/script-score.json', JSON.stringify(r, null, 2));
            const threshold = parseFloat(process.env.PR_SCORE_THRESHOLD || '7.0');
            console.log('average_score:', r?.average_score);
            if ((r?.average_score ?? 0) < threshold) {
              console.error('Score below threshold:', threshold);
              process.exit(1);
            }
            await nl.shutdown();
          "

      - name: Comment score on PR
        if: always() && github.event.pull_request.head.repo.full_name == github.repository
        uses: actions/github-script@v9
        with:
          script: |
            const fs = require('fs');
            let body = '## PR Quality Score Gate\n\n';
            try {
              const score = JSON.parse(fs.readFileSync('output/script-score.json', 'utf-8'));
              body += `**Average score:** ${score.average_score?.toFixed(2) ?? 'n/a'}/10  \n`;
              body += `**Lock-ready:** ${score.lock_ready ? 'yes' : 'no'}  \n`;
              body += `**Weakest dimension:** ${score.weakest_criterion ?? 'n/a'}  \n\n`;
              if (score.improvement_notes?.length) {
                body += '### Top suggestions\n';
                for (const n of score.improvement_notes.slice(0, 3)) body += `- ${n}\n`;
              }
            } catch {
              body += '_Score not available — quality gate skipped (no Vertex credentials in secrets)._';
            }
            github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              body,
            });

